"""Slow independent reference transcribed directly from PROTOCOL.md.

Used only for cross-checking the submission; never shipped.
"""
import hashlib
import json
from math import gcd
from itertools import product


def band(entries, eps):
    """Naive band: enumerate every (lo, hi) endpoint pair explicitly."""
    best = None  # (mass, lo, hi)
    values = sorted({v for v, _w in entries})
    for lo in values:
        for hi in values:
            if hi < lo:
                continue
            if 1000000 * (hi - lo) > eps * hi:
                continue
            mass = sum(w for v, w in entries if lo <= v <= hi)
            if best is None or mass > best[0] or (mass == best[0] and (lo < best[1] or (lo == best[1] and hi < best[2]))):
                best = (mass, lo, hi)
    mass, lo, hi = best
    total = sum(v * w for v, w in entries if lo <= v <= hi)
    return total // mass, mass


def whash(seed, r, t, a, b):
    d = ("%d:%d:%d:%d:%d" % (seed, r, t, a, b)).encode("ascii")
    return int.from_bytes(hashlib.sha256(d).digest()[:8], "big")


class Ref:
    def __init__(self, topology, settings):
        self.settings = settings
        self.nodes = {n["id"]: n for n in topology["nodes"]}
        self.name = {n["id"]: n["name"] for n in topology["nodes"]}
        self.id_by_name = {n["name"]: n["id"] for n in topology["nodes"]}
        self.ext = sorted(self.id_by_name[x] for x in topology["external_nodes"])
        links = []
        for l in topology["links"]:
            u, v = l["source"], l["target"]
            if u > v:
                u, v = v, u
            links.append((u, v, l["capacity"]))
        self.links = sorted(links)
        flows = []
        for e in self.ext:
            flows.append((-1, e))
            flows.append((e, -1))
        for (u, v, _c) in self.links:
            flows.append((u, v))
            flows.append((v, u))
        self.flows = sorted(flows)
        cap = {}
        for (u, v, c) in self.links:
            cap[(u, v)] = cap[(v, u)] = c
        for e in self.ext:
            cap[(-1, e)] = cap[(e, -1)] = self.nodes[e]["external_capacity"]
        self.cap = cap
        keys = {}
        self.flow_keys = {}
        for f in self.flows:
            a, b = f
            if a == -1:
                ks = ["low_%s_origination" % self.name[b]]
            elif b == -1:
                ks = ["low_%s_termination" % self.name[a]]
            else:
                ks = ["low_%s_egress_to_%s" % (self.name[a], self.name[b]),
                      "low_%s_ingress_from_%s" % (self.name[b], self.name[a])]
            self.flow_keys[f] = ks
            for k in ks:
                keys[k] = f
        self.key_flow = keys
        self.all_keys = sorted(keys)
        self.counters = {k: None for k in self.all_keys}  # value or None (missing)
        self.demands = {(s, d): 0 for s in self.ext for d in self.ext if s != d}
        self.paths = None
        self.cache = {}          # key -> publication
        self.recency = {}        # key -> stamp
        self.stamp = 0
        self.snaps = {}

    # ---- patch
    def patch(self, ev):
        if set(ev.keys()) != {"op", "demands", "counters"}:
            return {"op": "patch", "accepted": False}
        dem, cnt = ev["demands"], ev["counters"]
        if type(dem) is not list or type(cnt) is not dict:
            return {"op": "patch", "accepted": False}
        seen = set()
        du, cu = [], []
        for e in dem:
            if not isinstance(e, list) or len(e) != 3:
                return {"op": "patch", "accepted": False}
            if not all(type(x) is int for x in e):
                return {"op": "patch", "accepted": False}
            s, d, v = e
            if s == d or s not in self.ext or d not in self.ext:
                return {"op": "patch", "accepted": False}
            if (s, d) in seen:
                return {"op": "patch", "accepted": False}
            seen.add((s, d))
            if not (0 <= v <= 10 ** 9):
                return {"op": "patch", "accepted": False}
            du.append((s, d, v))
        for k, cell in cnt.items():
            if k not in self.key_flow:
                return {"op": "patch", "accepted": False}
            if cell is None:
                cu.append((k, None))
                continue
            if type(cell) is not dict:
                return {"op": "patch", "accepted": False}
            if "perturbed" not in cell:
                return {"op": "patch", "accepted": False}
            if not set(cell) <= {"perturbed", "ground_truth", "corrected", "confidence"}:
                return {"op": "patch", "accepted": False}
            p = cell["perturbed"]
            if p is None:
                cu.append((k, None))
                continue
            if type(p) is not int:
                return {"op": "patch", "accepted": False}
            if not (0 <= p <= self.cap[self.key_flow[k]]):
                return {"op": "patch", "accepted": False}
            cu.append((k, p))
        for (s, d, v) in du:
            self.demands[(s, d)] = v
        for (k, v) in cu:
            self.counters[k] = v
        return {"op": "patch", "accepted": True}

    # ---- routes
    def routes(self, ev):
        raw = ev["paths"]
        if raw is None:
            self.paths = None
        else:
            bundles = {}
            for sn, db in raw.items():
                si = self.id_by_name[sn]
                for dn, items in db.items():
                    di = self.id_by_name[dn]
                    bundles[(si, di)] = [(tuple(it["path"]), it["weight"]) for it in items]
            self.paths = bundles
        return {"op": "routes", "accepted": True}

    # ---- predictions
    def predict(self):
        out = {e: 0 for e in self.ext}
        inc = {e: 0 for e in self.ext}
        for (s, d), v in self.demands.items():
            out[s] += v
            inc[d] += v
        ext = {}
        for f in self.flows:
            a, b = f
            ext[f] = out[b] if a == -1 else inc[a] if b == -1 else None
        internal = None
        if self.paths is not None:
            internal = {}
            for f in self.flows:
                if f[0] != -1 and f[1] != -1:
                    total = 0
                    for (s, d), items in self.paths.items():
                        dem = self.demands[(s, d)]
                        for (path, w) in items:
                            for x, y in zip(path, path[1:]):
                                hop = (self.id_by_name[x], self.id_by_name[y])
                                if hop == f:
                                    total += dem * w
                    internal[f] = total // 1000
                else:
                    internal[f] = ext[f]
        return internal, ext

    def pool_of(self, f, internal, ext):
        pool = []
        for k in self.flow_keys[f]:
            v = self.counters[k]
            if v is not None:
                pool.append(v)
        if self.paths is not None:
            pv = internal[f] if (f[0] != -1 and f[1] != -1) else ext[f]
            pool.append(min(pv, self.cap[f]))
        return pool

    # ---- repair
    def repair_pub(self):
        s = self.settings
        eps = s["epsilon"]
        T = s["trials"]
        seed = s["seed"]
        internal, ext = self.predict()
        pools = {f: self.pool_of(f, internal, ext) for f in self.flows}

        def sample(f, r, t, fixed):
            if f in fixed:
                return fixed[f]
            pool = pools[f]
            if not pool:
                return 0
            return pool[whash(seed, r, t, f[0], f[1]) % len(pool)]

        routers = sorted({x for f in self.flows for x in f if x != -1})

        def real_ends(f):
            return [x for x in f if x != -1]

        def incident(r):
            return [f for f in self.flows if r in f]

        def router_item(f, r, fixed):
            rems = []
            for t in range(T):
                insum = 0
                outsum = 0
                for g in incident(r):
                    v = sample(g, r, t, fixed)
                    if g[1] == r:
                        insum += v
                    if g[0] == r:
                        outsum += v
                # target's own sampled value cancels from the remainder
                if f[1] == r and f[0] != r:  # incoming
                    rem = outsum - (insum - sample(f, r, t, fixed))
                else:  # outgoing
                    rem = insum - (outsum - sample(f, r, t, fixed))
                if rem < 0:
                    rem = 0
                if rem > self.cap[f]:
                    rem = self.cap[f]
                rems.append((rem, 1))
            return band(rems, eps)

        def flow_item(f, fixed):
            entries = [(v, T) for v in pools[f]]
            for r in real_ends(f):
                rep, mass = router_item(f, r, fixed)
                entries.append((rep, mass))
            return band(entries, eps)

        fixed = {}
        order = []
        values = {}
        conf = {}
        remaining = set(self.flows)
        while remaining:
            best = None
            for f in sorted(remaining):
                c, sup = flow_item(f, fixed)
                if best is None or sup > best[1] or (sup == best[1] and f < best[0]):
                    best = (f, sup, c)
            f, sup, c = best
            values[f] = c
            g = gcd(sup, T)
            conf[f] = (sup // g, T // g)
            order.append(list(f))
            fixed[f] = c
            remaining.discard(f)
        links = [list(f) + [values[f], conf[f][0], conf[f][1]] for f in self.flows]
        counters = {}
        for f in self.flows:
            for k in self.flow_keys[f]:
                counters[k] = {"corrected": values[f], "confidence": [conf[f][0], conf[f][1]]}
        return links, order, counters

    def cache_key(self):
        ckey = tuple((k, self.counters[k]) for k in self.all_keys)
        dkey = tuple(sorted(self.demands.items()))
        rkey = None
        if self.paths is not None:
            entries = []
            for (s, d), items in self.paths.items():
                for (path, w) in items:
                    entries.append((self.name[s], self.name[d], path, w))
            rkey = tuple(sorted(entries))
        s = self.settings
        return (ckey, dkey, rkey, s["seed"], s["trials"], s["epsilon"])

    def do_repair(self, ev):
        key = self.cache_key()
        hit = key in self.cache
        if hit:
            links, order, counters = self.cache[key]
            self.stamp += 1
            self.recency[key] = self.stamp
        else:
            links, order, counters = self.repair_pub()
            self.cache[key] = (links, order, counters)
            self.stamp += 1
            self.recency[key] = self.stamp
            if self.settings["cache_slots"] < len(self.cache):
                # evict least recently repaired
                victim = min(self.cache, key=lambda k: self.recency[k])
                del self.cache[victim]
                del self.recency[victim]
        self.snaps[ev["id"]] = (json.loads(json.dumps(links)),
                               json.loads(json.dumps(order)),
                               json.loads(json.dumps(counters)))
        return {"op": "repair", "id": ev["id"], "cache_hit": hit,
                "links": json.loads(json.dumps(links)),
                "order": json.loads(json.dumps(order)),
                "counters": json.loads(json.dumps(counters))}

    def do_validate(self, ev):
        snap = self.snaps.get(ev["id"])
        if snap is None:
            return {"op": "validate", "id": ev["id"], "checked": 0,
                    "passed": 0, "consistent": None, "failed": []}
        links, order, counters = snap
        s = self.settings
        cnum, cden = s["cutoff"]
        gnum, gden = s["gamma"]
        internal, ext = self.predict()
        checked = passed = 0
        failed = []
        for row in links:
            (a, b, value, num, den) = row
            if num * cden < cnum * den:
                continue
            f = (a, b)
            if a != -1 and b != -1:
                if internal is None:
                    continue
                pred = internal[f]
            else:
                pred = ext[f]
            X = value * 1000000
            Y = pred * (1000000 - s["bias"])
            ok = 1000000 * abs(X - Y) <= s["tau"] * max(X, Y)
            cells = self.flow_keys[f]
            checked += len(cells)
            if ok:
                passed += len(cells)
            else:
                failed.extend(cells)
        failed.sort()
        consistent = None if checked == 0 else (passed * gden >= gnum * checked)
        return {"op": "validate", "id": ev["id"], "checked": checked,
                "passed": passed, "consistent": consistent, "failed": failed}

    def apply(self, ev):
        if ev["op"] == "patch":
            return self.patch(ev)
        if ev["op"] == "routes":
            return self.routes(ev)
        if ev["op"] == "repair":
            return self.do_repair(ev)
        if ev["op"] == "validate":
            return self.do_validate(ev)
        raise ValueError("unknown op")


def run_reference(request):
    out = []
    for s in request["streams"]:
        ref = Ref(s["topology"], s["settings"])
        out.append({"events": [ref.apply(e) for e in s["events"]]})
    return {"streams": out}
